package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

func main() {
	fmt.Println("GOMAXPROCS:", runtime.GOMAXPROCS(0))

	// 1) 多个 goroutine 并发 IO
	var wg sync.WaitGroup
	start := time.Now()
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			time.Sleep(100 * time.Millisecond) // 模拟 IO 等待
			fmt.Printf("goroutine %d done\n", id)
		}(i)
	}
	wg.Wait()
	fmt.Println("io elapsed:", time.Since(start).Round(10*time.Millisecond))
	// 总耗时约 100ms，5 个 goroutine 并发

	// 2) CPU 密集 goroutine 不会阻止其他 goroutine 运行
	//    （Go 1.14+ 异步抢占，但热点计算仍占用核心资源）
	go func() {
		end := time.Now().Add(200 * time.Millisecond)
		for time.Now().Before(end) {
			// CPU 热循环
		}
	}()

	go func() {
		time.Sleep(50 * time.Millisecond)
		fmt.Println("other goroutine ran during CPU hotspot")
	}()
	time.Sleep(300 * time.Millisecond)
}
